UPDATE ETR_ENTRUST SET ENTRUST_STATUS = '06' WHERE ENTRUST_ID IN ( SELECT ENTRUST_ID FROM ETR_ENTRUST WHERE ENTRUST_STATUS IN ( #{ENTRUST_STATUS_01}, #{ENTRUST_STATUS_02}, #{ENTRUST_STATUS_03}, #{ENTRUST_STATUS_05},#{ENTRUST_STATUS_08} )
AND MDATE <= TO_DATE(#{sysDate},'YYYY-MM-DD')
)

UPDATE ETR_DISTRIBUTE SET REC_STATUS = '06' WHERE ENTRUST_ID IN ( SELECT ENTRUST_ID FROM ETR_ENTRUST WHERE ENTRUST_STATUS IN ( #{ENTRUST_STATUS_01}, #{ENTRUST_STATUS_02}, #{ENTRUST_STATUS_03}, #{ENTRUST_STATUS_05},#{ENTRUST_STATUS_08} )
AND MDATE <= TO_DATE(#{sysDate},'YYYY-MM-DD')
)

UPDATE ETR_ENTRUST SET BUSINESS_MODEL = 'FVTPL',INV_AIM = 'FVTPL' WHERE ENTRUST_ID IN ( SELECT T1.ENTRUST_ID FROM REG_FIN_PRODUCT_DEAL T1 WHERE EXISTS( SELECT 1 FROM REG_FIN_PRODUCT_DEAL_TOTAL T2 WHERE T2.TOTLE_TRADE_ID = T1.TOTLE_TRADE_ID AND T2.TRADE_STATUS = '01' AND (T2.IS_CANCEL = 'N' OR T2.IS_CANCEL IS NULL) AND T2.TRADE_DATE = TO_DATE(#{sysDate},'YYYY-MM-DD')) AND T1.INV_AIM = 'FVTPL' UNION ALL SELECT T1.ENTRUST_ID FROM IBU_QUOTE_ETR_RE T1 WHERE EXISTS ( SELECT 1 FROM IBU_QUOTE_BOND T2 WHERE T2.QUOTE_ID = T1.QUOTE_ID AND T2.QUOTE_DATE = TO_DATE(#{sysDate},'YYYY-MM-DD')
and T2.TRADE_STATUS in
#{item}
) AND T1.INV_AIM = 'FVTPL' )
